import { describe, expect, it } from "vitest";

import {
  buildCodeSamples,
  buildReference,
  preparePrivateRequest,
  type OpenAPIDocument,
} from "./reference";

const document: OpenAPIDocument = {
  openapi: "3.1.0",
  info: { title: "Supermetry API", version: "1.0.0" },
  paths: {
    "/api/public/v1/stats/summary": {
      get: {
        operationId: "statsSummary",
        summary: "Get summary statistics",
        tags: ["Statistics"],
        parameters: [
          {
            name: "site_id",
            in: "query",
            required: true,
            schema: { type: "integer" },
          },
          {
            name: "period",
            in: "query",
            required: true,
            schema: { type: "string", example: "30d" },
          },
          {
            name: "date_from",
            in: "query",
            schema: { type: "string", example: "2026-10-01" },
          },
        ],
        responses: {
          "200": {
            description: "Summary",
            content: {
              "application/json": {
                schema: { $ref: "#/components/schemas/QueryResponse" },
                example: { totals: { visitors: 42 } },
              },
            },
          },
          "401": { $ref: "#/components/responses/Unauthorized" },
        },
      },
    },
  },
  components: {
    responses: {
      Unauthorized: {
        description: "Authentication is required or invalid.",
        content: {
          "application/problem+json": {
            schema: { $ref: "#/components/schemas/Problem" },
          },
        },
      },
    },
    schemas: {
      QueryResponse: {
        type: "object",
        properties: { totals: { type: "object" } },
      },
      Problem: {
        type: "object",
        example: {
          type: "https://supermetry.com/problems/bad-request",
          title: "Bad request",
          status: 400,
        },
      },
    },
  },
};

describe("buildReference", () => {
  it("groups operations by tag and exposes parameters, schemas, and response examples", () => {
    const reference = buildReference(document);

    expect(reference.groups).toHaveLength(1);
    expect(reference.groups[0]?.name).toBe("Statistics");
    expect(reference.groups[0]?.operations[0]).toMatchObject({
      method: "GET",
      path: "/api/public/v1/stats/summary",
      summary: "Get summary statistics",
      schemaNames: ["Problem", "QueryResponse"],
      responseExamples: [
        { status: "200", value: { totals: { visitors: 42 } } },
        {
          status: "401",
          value: {
            type: "https://supermetry.com/problems/unauthorized",
            title: "Unauthorized",
            status: 401,
            detail: "Authentication is required or invalid.",
          },
        },
      ],
    });
    expect(reference.schemas.QueryResponse).toEqual(
      document.components?.schemas?.QueryResponse,
    );
  });

  it("derives a readable example when a response only declares a schema", () => {
    const withoutExample = structuredClone(document);
    const response =
      withoutExample.paths["/api/public/v1/stats/summary"]?.get?.responses?.[
        "200"
      ];
    if (response?.content?.["application/json"])
      delete response.content["application/json"].example;

    expect(
      buildReference(withoutExample).groups[0]?.operations[0]?.responseExamples,
    ).toEqual([
      { status: "200", value: { totals: {} } },
      {
        status: "401",
        value: {
          type: "https://supermetry.com/problems/unauthorized",
          title: "Unauthorized",
          status: 401,
          detail: "Authentication is required or invalid.",
        },
      },
    ]);
  });
});

describe("buildCodeSamples", () => {
  it("builds authenticated curl, JavaScript, Python, and Go requests", () => {
    const operation = buildReference(document).groups[0]!.operations[0]!;
    const samples = buildCodeSamples(
      operation,
      "https://analytics.example.com",
      7,
    );

    expect(samples.curl).toContain("Authorization: Bearer <api-key>");
    expect(samples.curl).toContain("site_id=7&period=30d");
    expect(samples.curl).not.toContain("date_from");
    expect(samples.javascript).toContain(
      "headers: { Authorization: 'Bearer <api-key>' }",
    );
    expect(samples.python).toContain(
      "headers={'Authorization': 'Bearer <api-key>'}",
    );
    expect(samples.go).toContain(
      'req.Header.Set("Authorization", "Bearer <api-key>")',
    );
  });

  it("includes a JSON request example for operations with a body", () => {
    const operation = {
      ...buildReference(document).groups[0]!.operations[0]!,
      method: "POST" as const,
      requestExample: { site_id: 7, metrics: ["visitors"] },
    };
    const samples = buildCodeSamples(
      operation,
      "https://analytics.example.com",
      7,
    );

    expect(samples.curl).toContain(
      '--data \'{"site_id":7,"metrics":["visitors"]}\'',
    );
    expect(samples.javascript).toContain("body: JSON.stringify({");
    expect(samples.python).toContain(
      "json={'site_id': 7, 'metrics': ['visitors']}",
    );
    expect(samples.go).toContain(
      'strings.NewReader(`{"site_id":7,"metrics":["visitors"]}`)',
    );
  });
});

describe("preparePrivateRequest", () => {
  it("rewrites the public route and supplies the selected site and parameter values", () => {
    const operation = buildReference(document).groups[0]!.operations[0]!;

    expect(preparePrivateRequest(operation, 7, { period: "7d" })).toEqual({
      method: "GET",
      path: "/api/private/stats/summary?site_id=7&period=7d",
      body: undefined,
    });
  });

  it("points a query body's site_id at the selected site", () => {
    const operation = {
      ...buildReference(document).groups[0]!.operations[0]!,
      method: "POST" as const,
      path: "/api/public/v1/query",
      parameters: [],
    };

    expect(
      preparePrivateRequest(operation, 7, {}, { site_id: 42, metrics: ["visitors"] }),
    ).toEqual({
      method: "POST",
      path: "/api/private/query",
      body: { site_id: 7, metrics: ["visitors"] },
    });
  });

  it("does not offer private execution for public-only endpoints", () => {
    const operation = {
      ...buildReference(document).groups[0]!.operations[0]!,
      path: "/api/public/v1/events",
    };

    expect(preparePrivateRequest(operation, 7, {})).toBeNull();
  });

  it("does not execute resource mutations from the read-only documentation console", () => {
    const operation = {
      ...buildReference(document).groups[0]!.operations[0]!,
      method: "DELETE" as const,
      path: "/api/public/v1/sites/{site_id}",
    };

    expect(preparePrivateRequest(operation, 7, {})).toBeNull();
  });
});

import '@testing-library/jest-dom/vitest'
import {
  QueryClient,
  QueryClientProvider,
  useQuery,
} from '@tanstack/react-query'
import { cleanup, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it } from 'vitest'
import {
  AuthorizationCacheBoundary,
  authorizationScope,
} from './authorization-cache'
import { profileKeys } from '@/features/profiles/api'

afterEach(cleanup)

describe('authorization cache lifecycle', () => {
  it('drops sensitive data before mounting content under a changed scope and on sign-out', () => {
    const client = new QueryClient()
    const keys = [
      profileKeys.detail(1, 7, 123),
      ['replay', 7, 'data', '123'],
      ['sessions', 7, 'list'],
      ['sites', 7, 'events'],
      ['retention', { site_id: 7, identity: 'profile' }],
    ]
    for (const key of keys)
      client.setQueryData(key, { private: 'prior access' })
    client.setQueryData(['stats', 7], { total: 10 })
    function Probe() {
      return (
        <p>
          {keys.some((key) => client.getQueryData(key))
            ? 'Cached sensitive data'
            : 'No sensitive cache'}
        </p>
      )
    }
    const view = render(
      <QueryClientProvider client={client}>
        <AuthorizationCacheBoundary scope="original">
          <Probe />
        </AuthorizationCacheBoundary>
      </QueryClientProvider>,
    )
    expect(screen.getByText('Cached sensitive data')).toBeVisible()
    view.rerender(
      <QueryClientProvider client={client}>
        <AuthorizationCacheBoundary scope="revoked">
          <Probe />
        </AuthorizationCacheBoundary>
      </QueryClientProvider>,
    )
    expect(screen.getByText('No sensitive cache')).toBeVisible()
    expect(screen.queryByText('Cached sensitive data')).not.toBeInTheDocument()
    expect(client.getQueryData(['stats', 7])).toEqual({ total: 10 })
    client.setQueryData(keys[0], { private: 'newly granted data' })
    view.unmount()
    expect(client.getQueryData(keys[0])).toBeUndefined()
  })

  it('cancels in-flight reads and does not restore their cache on a late response', async () => {
    const client = new QueryClient({
      defaultOptions: { queries: { retry: false } },
    })
    let finish!: (data: string) => void
    let signal: AbortSignal | undefined
    function Pending() {
      useQuery({
        queryKey: ['replay', 7, 'data', '123'],
        queryFn: (context) => {
          signal = context.signal
          return new Promise<string>((resolve) => {
            finish = resolve
          })
        },
      })
      return <p>Loading replay</p>
    }
    const view = render(
      <QueryClientProvider client={client}>
        <AuthorizationCacheBoundary scope="allowed">
          <Pending />
        </AuthorizationCacheBoundary>
      </QueryClientProvider>,
    )
    await waitFor(() => expect(signal).toBeDefined())
    view.rerender(
      <QueryClientProvider client={client}>
        <AuthorizationCacheBoundary scope="revoked">
          <p>Permission revoked</p>
        </AuthorizationCacheBoundary>
      </QueryClientProvider>,
    )
    expect(signal?.aborted).toBe(true)
    finish('private replay')
    await Promise.resolve()
    expect(client.getQueryData(['replay', 7, 'data', '123'])).toBeUndefined()
  })

  it('treats account, organization, role, grants, and site scope changes as new authorization contexts', () => {
    const membership = {
      org: { id: 1, name: 'Acme', slug: 'acme' },
      role: 'viewer' as const,
      sites: [{ id: 7, name: 'Docs' }],
      site_ids: [7],
      effective_capabilities: ['profiles.read'],
    }
    const original = authorizationScope(1, membership)
    for (const next of [
      authorizationScope(2, membership),
      authorizationScope(1, { ...membership, role: 'editor' }),
      authorizationScope(1, { ...membership, effective_capabilities: [] }),
      authorizationScope(1, { ...membership, site_ids: [], sites: [] }),
      authorizationScope(1, {
        ...membership,
        org: { ...membership.org, id: 2 },
      }),
    ])
      expect(next).not.toBe(original)
  })

  it('gives pages outside an organization their own authorization context', () => {
    const membership = { org: { id: 1, name: 'Acme', slug: 'acme' }, role: 'owner' as const, sites: [] }
    expect(authorizationScope(1, undefined)).toBe(authorizationScope(1, undefined))
    expect(authorizationScope(1, undefined)).not.toBe(authorizationScope(1, membership))
    expect(authorizationScope(1, undefined)).not.toBe(authorizationScope(2, undefined))
  })
})

package auth

import (
	"fmt"
	"testing"
	"time"
)

func TestLoginLimiterRejectedClientDoesNotConsumeAccountBudget(t *testing.T) {
	tests := []struct {
		name  string
		allow func(*loginLimiter, string, string, time.Time) bool
	}{
		{name: "login", allow: (*loginLimiter).allow},
		{name: "password reset", allow: (*loginLimiter).allowReset},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			limiter := newLoginLimiter()
			now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
			for i := 0; i < 20; i++ {
				if !tt.allow(limiter, fmt.Sprintf("other-%d", i), "flooder", now) {
					t.Fatalf("flooder warm-up attempt %d rejected", i+1)
				}
			}
			if tt.allow(limiter, "victim", "flooder", now) {
				t.Fatal("client over its own limit was allowed")
			}
			for i := 0; i < 5; i++ {
				if !tt.allow(limiter, "victim", fmt.Sprintf("well-behaved-%d", i), now) {
					t.Fatalf("well-behaved client %d lost shared target budget", i+1)
				}
			}
		})
	}
}

func TestLoginLimiterHarnessCapacity(t *testing.T) {
	limiter := newLoginLimiter()
	limiter.setLoginCapacity(50)
	now := time.Date(2026, 10, 12, 0, 0, 0, 0, time.UTC)
	for attempt := 0; attempt < 50; attempt++ {
		if !limiter.allow("owner@example.test", "worker", now) {
			t.Fatalf("attempt %d rejected before configured capacity", attempt+1)
		}
	}
	if limiter.allow("owner@example.test", "worker", now) {
		t.Fatal("attempt beyond configured capacity was accepted")
	}
}

func TestLoginLimiterPairCannotExhaustSharedAccountBudget(t *testing.T) {
	limiter := newLoginLimiter()
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	for i := 0; i < accountClientCapacity; i++ {
		if !limiter.allow("victim", "attacker", now) {
			t.Fatalf("paired attempt %d rejected", i+1)
		}
	}
	if limiter.allow("victim", "attacker", now) {
		t.Fatal("attacker exceeded its account-client budget")
	}
	for _, client := range []string{"real-device", "another-device", "new-device"} {
		if !limiter.allow("victim", client, now) {
			t.Fatalf("%s was locked out by a different client", client)
		}
	}
}

func TestPruneBucketsEnforcesHardCap(t *testing.T) {
	const hardCap = 4096
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	buckets := make(map[string]bucket, hardCap+17)
	for i := 0; i < hardCap+17; i++ {
		buckets[fmt.Sprintf("key-%05d", i)] = bucket{tokens: 1, last: now.Add(time.Duration(i) * time.Nanosecond)}
	}

	pruneBuckets(buckets, now.Add(30*time.Second))

	if got := len(buckets); got != hardCap {
		t.Fatalf("bucket count = %d, want %d", got, hardCap)
	}
	if _, ok := buckets["key-00000"]; ok {
		t.Fatal("oldest bucket was not evicted")
	}
	if _, ok := buckets[fmt.Sprintf("key-%05d", hardCap+16)]; !ok {
		t.Fatal("newest bucket was evicted")
	}
}

func TestLoginLimiterAccountCeilingSlowsDistributedGuessing(t *testing.T) {
	limiter := newLoginLimiter()
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	for i := 0; i < accountCeilingPerMinute; i++ {
		if !limiter.allow("victim", fmt.Sprintf("client-%d", i), now) {
			t.Fatalf("attempt %d from a distinct client rejected before the ceiling", i+1)
		}
	}
	if limiter.allow("victim", "client-extra", now) {
		t.Fatal("account ceiling did not slow a distributed attack")
	}
	if !limiter.allow("victim", "client-extra", now.Add(2*time.Minute)) {
		t.Fatal("ceiling did not recover after the window")
	}
}

func TestLoginLimiterSingleClientCannotReachAccountCeiling(t *testing.T) {
	limiter := newLoginLimiter()
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	for i := 0; i < 100; i++ {
		limiter.allow("victim", "attacker", now)
	}
	if !limiter.allow("victim", "real-user", now) {
		t.Fatal("one client locked the real user out of the account")
	}
}

func TestSecondFactorLimiterMapIsBounded(t *testing.T) {
	limiter := newSecondFactorLimiter(5, 5*time.Minute, 15*time.Minute)
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	for accountID := int64(1); accountID <= limiterBucketCap+17; accountID++ {
		attemptedAt := now.Add(time.Duration(accountID) * time.Nanosecond)
		attempt, allowed := limiter.begin(accountID, attemptedAt)
		if !allowed {
			t.Fatalf("account %d unexpectedly limited", accountID)
		}
		limiter.failed(attempt, attemptedAt)
	}
	if got := len(limiter.accounts); got != limiterBucketCap {
		t.Fatalf("second-factor account count = %d, want %d", got, limiterBucketCap)
	}
	if _, ok := limiter.accounts[1]; ok {
		t.Fatal("oldest second-factor account was not evicted")
	}
	if _, ok := limiter.accounts[limiterBucketCap+17]; !ok {
		t.Fatal("newest second-factor account was evicted")
	}
}

func TestSecondFactorLimiterReservesConcurrentAttemptBudget(t *testing.T) {
	limiter := newSecondFactorLimiter(5, 5*time.Minute, 15*time.Minute)
	now := time.Date(2026, 10, 10, 0, 0, 0, 0, time.UTC)
	attempts := make([]*secondFactorAttempt, 5)
	for i := range attempts {
		var allowed bool
		attempts[i], allowed = limiter.begin(42, now)
		if !allowed {
			t.Fatalf("attempt %d rejected before budget was reserved", i+1)
		}
	}
	if _, allowed := limiter.begin(42, now); allowed {
		t.Fatal("sixth concurrent attempt exceeded the account budget")
	}
	limiter.succeeded(attempts[0])
	if _, allowed := limiter.begin(42, now); !allowed {
		t.Fatal("successful concurrent attempt did not reset the account budget")
	}
}

package installer

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	_ "embed"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"text/template"
)

//go:embed templates/docker-compose.yml.tmpl
var composeTemplate string

// ComposeValues controls the generated Docker Compose file.
type ComposeValues struct {
	Version    string
	Image      string
	ListenHost string
	Port       string
	Updater    bool
	UpdaterGID string
}

// RenderCompose renders the bundled app and PostgreSQL services.
func RenderCompose(c ComposeValues) []byte {
	if c.Version == "" {
		c.Version = "latest"
	}
	tmpl := template.Must(template.New("compose").Option("missingkey=error").Parse(composeTemplate))
	var out bytes.Buffer
	if err := tmpl.Execute(&out, c); err != nil {
		panic(err)
	}
	return out.Bytes()
}

func prepareDockerBuildSource(ctx context.Context, opts Options) error {
	_, sourceURL, sourceDir := dockerSource(opts)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, sourceURL, nil)
	if err != nil {
		return err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("download Docker build source: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("download Docker build source: HTTP %d", resp.StatusCode)
	}
	if err := os.RemoveAll(sourceDir); err != nil {
		return fmt.Errorf("replace Docker build source: %w", err)
	}
	if err := os.MkdirAll(sourceDir, 0o755); err != nil {
		return fmt.Errorf("create Docker build source directory: %w", err)
	}
	return extractSourceArchive(resp.Body, sourceDir)
}

func dockerSource(opts Options) (archive, sourceURL, sourceDir string) {
	version := opts.Version
	if version == "" || version == "latest" {
		version = "main"
	}
	if version != "main" && !strings.HasPrefix(version, "v") {
		version = "v" + version
	}
	archive = filepath.Join(opts.Dir, "supermetry-"+version+".tar.gz")
	sourceDir = filepath.Join(opts.Dir, "src")
	sourceURL = "https://github.com/velixio/supermetry/archive/refs/heads/main.tar.gz"
	if version != "main" {
		sourceURL = "https://github.com/velixio/supermetry/archive/refs/tags/" + version + ".tar.gz"
	}
	return archive, sourceURL, sourceDir
}

func extractSourceArchive(r io.Reader, destination string) error {
	gz, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("open source archive: %w", err)
	}
	defer gz.Close()
	tree := tar.NewReader(gz)
	for {
		header, err := tree.Next()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return fmt.Errorf("read source archive: %w", err)
		}
		_, relative, ok := strings.Cut(filepath.ToSlash(header.Name), "/")
		if !ok || relative == "" {
			continue
		}
		relative = filepath.Clean(filepath.FromSlash(relative))
		if relative == "." || filepath.IsAbs(relative) || relative == ".." || strings.HasPrefix(relative, ".."+string(filepath.Separator)) {
			return fmt.Errorf("unsafe source archive path %q", header.Name)
		}
		target := filepath.Join(destination, relative)
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, os.FileMode(header.Mode)&0o755); err != nil {
				return err
			}
		case tar.TypeReg, tar.TypeRegA:
			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
				return err
			}
			file, err := os.OpenFile(target, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, os.FileMode(header.Mode)&0o755)
			if err != nil {
				return err
			}
			_, copyErr := io.Copy(file, tree)
			closeErr := file.Close()
			if copyErr != nil {
				return copyErr
			}
			if closeErr != nil {
				return closeErr
			}
		case tar.TypeSymlink:
			link := filepath.Clean(filepath.FromSlash(header.Linkname))
			if filepath.IsAbs(link) || link == ".." || strings.HasPrefix(link, ".."+string(filepath.Separator)) {
				return fmt.Errorf("unsafe source archive link %q", header.Linkname)
			}
			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
				return err
			}
			if err := os.Symlink(link, target); err != nil {
				return err
			}
		}
	}
}

